class Solution {
public:
    int minTotalDistance(vector<vector<int>>& grid) {
        vector<int> rows, cols;
        int R = grid.size(), C = grid[0].size();
        for (int r = 0; r < R; ++r) {
            for (int c = 0; c < C; ++c) {
                if (grid[r][c] == 1) rows.push_back(r);
            }
        }
        for (int c = 0; c < C; ++c) {
            for (int r = 0; r < R; ++r) {
                if (grid[r][c] == 1) cols.push_back(c);
            }
        }
        auto getDist = [](const vector<int>& coords) {
            int d = 0, i = 0, j = coords.size() - 1;
            while (i < j) {
                d += coords[j] - coords[i];
                i++;
                j--;
            }
            return d;
        };
        return getDist(rows) + getDist(cols);
    }
};

class Solution {
    public int minTotalDistance(int[][] grid) {
        List<Integer> rows = new ArrayList<>();
        List<Integer> cols = new ArrayList<>();
        int R = grid.length, C = grid[0].length;
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (grid[r][c] == 1) rows.add(r);
            }
        }
        for (int c = 0; c < C; c++) {
            for (int r = 0; r < R; r++) {
                if (grid[r][c] == 1) cols.add(c);
            }
        }
        return getDist(rows) + getDist(cols);
    }

    private int getDist(List<Integer> coords) {
        int d = 0, i = 0, j = coords.size() - 1;
        while (i < j) {
            d += coords.get(j) - coords.get(i);
            i++;
            j--;
        }
        return d;
    }
}

